/* Sélecteur de balise universel */
body {
  font-family: Arial, sans-serif;
  background-color: #f8fafc;
  color: #1e293b;
}

/* Sélecteur d'identifiant unique (#) */
#titre {
  text-align: center;
  color: #2563eb;
  text-transform: uppercase;
}

/* Sélecteur de classe réutilisable (.) */
.L1 {
  background-color: #f1f5f9;
  font-weight: bold;
}

/* Pseudo-classe d'état :hover au survol */
input[type="submit"]:hover {
  background-color: #1d4ed8;
  cursor: pointer;
}

fieldset {
  width: 550px;
  margin: 20px auto; /* Centrage horizontal automatique */
  padding: 15px 25px;
  border: 2px solid #3b82f6;
  border-radius: 8px;
  background-color: #ffffff;
  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1);
}

label {
  display: inline-block;
  width: 180px; /* Largeur fixe pour aligner tous les champs */
  font-weight: 600;
  margin-bottom: 8px;
  color: #334155;
}

input[type="text"],
input[type="number"],
select {
  width: 260px;
  padding: 6px 10px;
  border: 1px solid #cbd5e1;
  border-radius: 4px;
}

input[type="submit"] {
  background-color: #2563eb;
  color: #ffffff;
  padding: 8px 20px;
  border: none;
  border-radius: 6px;
  font-size: 14px;
  /* Définition de la transition fluide */
  transition: all 1s ease-in-out;
}

input[type="submit"]:hover {
  background-color: #1d4ed8;
  transform: scale(1.1); /* Agrandissement de 10% */
  opacity: 0.9;
}
